const body = $json.body;
const data = body.data || {};
const key = data.key || {};
const message = data.message || {};
const text = message.conversation
  || (message.extendedTextMessage && message.extendedTextMessage.text)
  || (message.buttonsResponseMessage && message.buttonsResponseMessage.selectedDisplayText)
  || (message.listResponseMessage && message.listResponseMessage.title)
  || '';
const remoteJid = key.remoteJid || '';
if (remoteJid.includes('@g.us')) return [];
const phone = remoteJid.replace('@s.whatsapp.net', '');
return [{ json: { phone, name: data.pushName || 'Pelanggan', message: text, messageLower: text.toLowerCase().trim(), instance: body.instance || $env.EVOLUTION_INSTANCE, messageId: key.id } }];

const phone = $json.phone;
const msg = $json.messageLower;
const originalMsg = $json.message;
const instance = $json.instance;
const parts = originalMsg.trim().split(/\s+/);
let staffAction = 'help';
let targetOrderId = null;
let quickResponse = '';

if (msg.startsWith('selesai ') && parts[1]) {
  targetOrderId = parts[1].toUpperCase();
  staffAction = 'complete';
} else if (msg.startsWith('batal ') && parts[1]) {
  targetOrderId = parts[1].toUpperCase();
  staffAction = 'cancel';
} else if (msg === 'status' || msg === 'daftar' || msg === 'ringkasan') {
  staffAction = 'status';
} else {
  staffAction = 'help';
  quickResponse = '*PERINTAH STAFF*\n\nSELESAI [ID] — Pesanan siap, notif customer\nBALT [ID] — Batalkan pesanan\nSTATUS — Ringkasan pesanan hari ini\n\nContoh: SELESAI ORD-123456';
}
return [{ json: { phone, instance, staffAction, targetOrderId, quickResponse, originalMsg } }];

const cmd = $('Detect Staff Command').item.json;
const orderItems = $input.all();
let staffMsg = '';
let customerPhone = null;
let customerMsg = '';
let newStatus = null;

if (cmd.staffAction === 'help') {
  staffMsg = cmd.quickResponse;
} else if (orderItems.length === 0 || !orderItems[0].json.order_id) {
  staffMsg = `❌ Pesanan *${cmd.targetOrderId}* tidak ditemukan.`;
} else {
  const order = orderItems[0].json;
  customerPhone = String(order.phone);
  if (cmd.staffAction === 'complete') {
    newStatus = 'done';
    customerMsg = `Halo ${order.customer_name}! 🍽️\n\nPesanan kamu *${cmd.targetOrderId}* sudah siap!\n\nSilakan ambil di kasir.\nTerima kasih sudah memesan! 🙏`;
    staffMsg = `✅ *${cmd.targetOrderId}* ditandai selesai.\nNotif dikirim ke ${customerPhone}.`;
  } else if (cmd.staffAction === 'cancel') {
    newStatus = 'cancelled';
    customerMsg = `Maaf ${order.customer_name},\n\nPesanan *${cmd.targetOrderId}* harus kami batalkan.\n\nInfo: ${$env.RESTAURANT_PHONE}\nMohon maaf atas ketidaknyamanannya. 🙏`;
    staffMsg = `❌ *${cmd.targetOrderId}* dibatalkan.\nNotif dikirim ke ${customerPhone}.`;
  }
}

return [{ json: { staffMsg, customerPhone, customerMsg, newStatus, targetOrderId: cmd.targetOrderId, instance: cmd.instance, staffPhone: cmd.phone } }];

const msgData = $('Extract Message Data').item.json;
const sessionItems = $('Get Session').all();
const menuItems = $('Read Menu from Sheets').all().map(i => i.json);

const phone = msgData.phone;
const name = msgData.name;
const msg = msgData.messageLower;
const originalMsg = msgData.message;
const instance = msgData.instance;

let session = {};
if (sessionItems.length > 0 && sessionItems[0].json && sessionItems[0].json.phone) {
  session = sessionItems[0].json;
}
const state = session.state || 'start';

// ── HELPERS ──────────────────────────────────────────────────────────────────────────────────────────
function fmtRp(n) { return 'Rp ' + Number(n).toLocaleString('id-ID'); }

function mainMenu(name) {
  return `*RESTORAN SASAK LOMBOK*\nHalo, ${name}! Selamat datang!\n\n1 - Lihat Menu Makanan\n2 - Pesan Makanan\n3 - Reservasi Meja\n4 - Jam Operasional\n5 - Lokasi & Alamat\n6 - Hubungi Kami\n\nKetik angka untuk memilih`;
}

function buildFoodMenu() {
  const available = menuItems.filter(i => String(i.available).toLowerCase() === 'true' || i.available === true);
  if (available.length === 0) return 'Menu sedang diperbarui. Hubungi kami: ' + $env.RESTAURANT_PHONE;
  const cats = {};
  available.forEach(i => { if (!cats[i.category]) cats[i.category] = []; cats[i.category].push(i); });
  let text = '*MENU RESTORAN SASAK LOMBOK*\n\n';
  Object.entries(cats).forEach(([cat, items]) => {
    text += `*${cat}*\n`;
    items.forEach(i => { text += `• ${i.name}: ${fmtRp(i.price)}\n`; });
    text += '\n';
  });
  text += 'Untuk memesan ketik *2* atau *pesan*';
  return text;
}

function parseOrder(orderText) {
  const available = menuItems.filter(i => String(i.available).toLowerCase() === 'true' || i.available === true);
  const parts = orderText.split(',').map(p => p.trim()).filter(p => p);
  let breakdown = [], total = 0, unmatched = [];
  parts.forEach(part => {
    const qtyMatch = part.match(/^(\d+)\s+(.+)$/);
    const qty = qtyMatch ? parseInt(qtyMatch[1]) : 1;
    const itemName = (qtyMatch ? qtyMatch[2] : part).trim().toLowerCase();
    const found = available.find(m =>
      m.name.toLowerCase().includes(itemName) ||
      itemName.includes(m.name.toLowerCase().split(' ')[0]) ||
      itemName.includes(m.name.toLowerCase().split(' ').slice(0,2).join(' '))
    );
    if (found) {
      const subtotal = qty * Number(found.price);
      total += subtotal;
      breakdown.push(`${qty}x ${found.name} = ${fmtRp(subtotal)}`);
    } else {
      unmatched.push(`${qty}x ${itemName} (tidak ditemukan)`);
    }
  });
  return { breakdown, total, unmatched };
}

// ── ROUTING ─────────────────────────────────────────────────────────────────────────────────────────
const GREET = ['halo','hai','hello','hi','mulai','start','help','menu','0','batal','kembali','home'];
let responseText = '', newState = state, sessionUpdate = {};

if (GREET.includes(msg)) {
  responseText = mainMenu(name); newState = 'main_menu';
}
// ── MAIN MENU ───────────────────────────────────────────────────────────────────────────────────
else if (state === 'start' || state === 'main_menu') {
  if (msg === '1' || msg.includes('lihat menu')) { responseText = buildFoodMenu(); }
  else if (msg === '2' || msg.includes('pesan') || msg.includes('order')) {
    responseText = '*PESAN MAKANAN*\n\nKetik pesanan kamu, contoh:\n2 Ayam Taliwang Pedas, 1 Plecing Kangkung, 2 Es Kelapa Muda\n\nLihat menu? Ketik *1*\nKetik *0* untuk batal';
    newState = 'ordering';
  }
  else if (msg === '3' || msg.includes('reservasi') || msg.includes('booking')) {
    responseText = '*RESERVASI MEJA*\n\nBerapa orang yang akan datang?\nKetik *0* untuk batal';
    newState = 'reservation_guests';
  }
  else if (msg === '4' || msg.includes('jam') || msg.includes('buka')) { responseText = '*JAM OPERASIONAL*\n\nSenin - Minggu\n10.00 - 22.00 WITA\n\nKetik *0* untuk menu utama'; }
  else if (msg === '5' || msg.includes('lokasi') || msg.includes('alamat')) { responseText = `*LOKASI*\n\n${$env.RESTAURANT_ADDRESS}\n\nGoogle Maps: ${$env.RESTAURANT_MAPS}\n\nKetik *0* untuk menu utama`; }
  else if (msg === '6' || msg.includes('hubungi') || msg.includes('kontak')) { responseText = `*HUBUNGI KAMI*\n\nWhatsApp: ${$env.RESTAURANT_PHONE}\nInstagram: @restoran.sasak.lombok\n\nJam 10.00 - 22.00 WITA`; }
  else { responseText = mainMenu(name); newState = 'main_menu'; }
}
// ── ORDERING ────────────────────────────────────────────────────────────────────────────────────
else if (state === 'ordering') {
  if (originalMsg && originalMsg.length > 3) {
    const { breakdown, total, unmatched } = parseOrder(originalMsg);
    sessionUpdate.pending_order = originalMsg;
    sessionUpdate.order_total = String(total);
    let confirmText = '*KONFIRMASI PESANAN*\n\n';
    if (breakdown.length > 0) { breakdown.forEach(l => { confirmText += l + '\n'; }); confirmText += '\n'; }
    if (unmatched.length > 0) { confirmText += '⚠️ Tidak dikenali:\n'; unmatched.forEach(l => { confirmText += l + '\n'; }); confirmText += '\n'; }
    if (total > 0) confirmText += `*Total: ${fmtRp(total)}*\n\n`;
    confirmText += 'Sudah benar?\nKetik *ya* untuk konfirmasi\nKetik *tidak* untuk ubah\nKetik *0* untuk batal';
    responseText = confirmText; newState = 'order_confirm';
  } else { responseText = 'Masukkan pesanan kamu\nContoh: 2 Ayam Taliwang, 1 Plecing Kangkung\n\nKetik *0* untuk batal'; }
}
else if (state === 'order_confirm') {
  if (['ya','yes','iya'].includes(msg)) { responseText = 'Siapa nama pemesan?\n\nKetik *0* untuk batal'; newState = 'order_name'; }
  else if (['tidak','no','bukan'].includes(msg)) { responseText = 'Silakan ketik ulang pesanan kamu:\n\nKetik *0* untuk batal'; newState = 'ordering'; }
  else { responseText = 'Ketik *ya* untuk konfirmasi atau *tidak* untuk ubah pesanan'; }
}
else if (state === 'order_name') {
  if (originalMsg && originalMsg.length > 1) {
    sessionUpdate.order_customer_name = originalMsg;
    responseText = `Halo ${originalMsg}! Pesanan untuk:\n\n1 - Makan di tempat (Dine-in)\n2 - Bawa pulang (Take-away)\n\nKetik *1* atau *2*`;
    newState = 'order_type';
  }
}
else if (state === 'order_type') {
  const isDineIn = msg === '1' || msg.includes('dine') || msg.includes('tempat');
  const isTakeAway = msg === '2' || msg.includes('bawa') || msg.includes('take');
  if (isDineIn || isTakeAway) {
    sessionUpdate.order_type = isDineIn ? 'dine-in' : 'take-away';
    const cname = sessionUpdate.order_customer_name || session.order_customer_name || '-';
    const items = session.pending_order || '-';
    const total = sessionUpdate.order_total || session.order_total || '0';
    const tipe = isDineIn ? 'Makan di tempat' : 'Bawa pulang';
    responseText = `*KONFIRMASI AKHIR*\n\nPesanan: ${items}\nNama: ${cname}\nTipe: ${tipe}${total !== '0' ? '\nTotal: ' + fmtRp(total) : ''}\n\nKetik *konfirmasi* untuk selesai\nKetik *0* untuk batal`;
    newState = 'order_final';
  } else { responseText = 'Ketik *1* untuk makan di tempat atau *2* untuk bawa pulang'; }
}
else if (state === 'order_final') {
  if (msg === 'konfirmasi' || msg === 'ya' || msg === 'yes') {
    const orderId = 'ORD-' + Date.now().toString().slice(-6);
    const total = session.order_total || sessionUpdate.order_total || '0';
    sessionUpdate.last_order_id = orderId; sessionUpdate.order_status = 'confirmed';
    responseText = `*PESANAN BERHASIL!*\n\nNomor: *${orderId}*\nEstimasi: 30-45 menit${total !== '0' ? '\nTotal: ' + fmtRp(total) : ''}\n\nTerima kasih sudah memesan di Restoran Sasak Lombok!\n\nKetik *0* untuk menu utama`;
    newState = 'main_menu';
  } else { responseText = 'Ketik *konfirmasi* untuk selesaikan atau *0* untuk batal'; }
}
// ── RESERVATION ──────────────────────────────────────────────────────────────────────────────────
else if (state === 'reservation_guests') {
  const n = parseInt((msg.match(/\d+/) || [])[0]);
  if (n >= 1 && n <= 50) { sessionUpdate.reservation_guests = String(n); responseText = 'Tanggal kedatangan?\nContoh: 25 Juni 2025\n\nKetik *0* untuk batal'; newState = 'reservation_date'; }
  else { responseText = 'Masukkan jumlah tamu (1-50), contoh: 4'; }
}
else if (state === 'reservation_date') {
  if (originalMsg && originalMsg.length > 2) { sessionUpdate.reservation_date = originalMsg; responseText = 'Jam kedatangan?\nContoh: 19:00\n\nKetik *0* untuk batal'; newState = 'reservation_time'; }
  else { responseText = 'Masukkan tanggal, contoh: 25 Juni 2025'; }
}
else if (state === 'reservation_time') {
  if (originalMsg && originalMsg.length > 1) { sessionUpdate.reservation_time = originalMsg; responseText = 'Nama untuk reservasi?\n\nKetik *0* untuk batal'; newState = 'reservation_name'; }
  else { responseText = 'Masukkan jam kedatangan, contoh: 19:00'; }
}
else if (state === 'reservation_name') {
  if (originalMsg && originalMsg.length > 1) {
    const resId = 'RES-' + Date.now().toString().slice(-6);
    sessionUpdate.reservation_name = originalMsg; sessionUpdate.last_reservation_id = resId;
    const g = session.reservation_guests || sessionUpdate.reservation_guests || '-';
    const d = session.reservation_date || sessionUpdate.reservation_date || '-';
    const t = session.reservation_time || sessionUpdate.reservation_time || '-';
    responseText = `*KONFIRMASI RESERVASI*\n\nNomor: *${resId}*\nNama: ${originalMsg}\nTamu: ${g} orang\nTanggal: ${d}\nJam: ${t}\n\nKetik *ya* untuk konfirmasi\nKetik *tidak* untuk ulang\nKetik *0* untuk batal`;
    newState = 'reservation_confirm';
  }
}
else if (state === 'reservation_confirm') {
  if (['ya','yes','iya'].includes(msg)) {
    sessionUpdate.reservation_status = 'confirmed';
    const rname = session.reservation_name || sessionUpdate.reservation_name || '-';
    const resId = session.last_reservation_id || sessionUpdate.last_reservation_id || '-';
    responseText = `*RESERVASI BERHASIL!*\n\nNomor: *${resId}*\nNama: ${rname}\n\nSampai jumpa di Restoran Sasak Lombok! 🌶️\nInfo: ${$env.RESTAURANT_PHONE}\n\nKetik *0* untuk menu utama`;
    newState = 'main_menu';
  } else if (['tidak','no'].includes(msg)) { responseText = 'Baik, mulai ulang reservasi.\n\nBerapa orang yang akan datang?'; newState = 'reservation_guests'; }
  else { responseText = 'Ketik *ya* untuk konfirmasi atau *tidak* untuk mulai ulang'; }
}
// ── AWAITING FEEDBACK ───────────────────────────────────────────────────────────────────────
else if (state === 'awaiting_feedback') {
  const rating = parseInt(msg);
  if (rating >= 1 && rating <= 5) {
    sessionUpdate.feedback_rating = String(rating);
    sessionUpdate.feedback_status = 'rated';
    responseText = `Terima kasih atas rating *${rating}/5* kamu! 🙏\nKami terus berusaha memberikan yang terbaik.\n\nKetik *0* untuk menu utama`;
    newState = 'main_menu';
  } else if (originalMsg.length > 5) {
    sessionUpdate.feedback_comment = originalMsg;
    responseText = 'Terima kasih masukannya!\n\nBerikan juga rating (ketik angka *1-5*):\n5=Sangat Puas, 4=Puas, 3=Cukup, 2=Kurang, 1=Sangat Kurang';
  } else {
    responseText = 'Ketik angka *1-5* untuk memberi rating:\n5=Sangat Puas, 4=Puas, 3=Cukup, 2=Kurang, 1=Sangat Kurang';
  }
}
else { responseText = mainMenu(name); newState = 'main_menu'; }

return [{ json: { phone, name, instance, responseText, newState, sessionUpdate: { ...sessionUpdate, state: newState, last_updated: new Date().toISOString() }, currentSession: session } }];

const d = $('Route & Build Response').item.json;
const s = d.currentSession;
const su = d.sessionUpdate;
const orderId = su.last_order_id || s.last_order_id;
const cname = su.order_customer_name || s.order_customer_name;
const items = s.pending_order;
const otype = su.order_type || s.order_type;
const total = su.order_total || s.order_total || '0';
const now = new Date().toLocaleString('id-ID', {timeZone: 'Asia/Makassar'});
return [{ json: {
  order_id: orderId, phone: d.phone, customer_name: cname, items, order_type: otype,
  order_total: total, status: 'confirmed', order_time: new Date().toISOString(),
  kitchen_msg: `*PESANAN BARU!*\nNo: ${orderId}\nNama: ${cname}\nHP: ${d.phone}\nPesanan: ${items}\nTipe: ${otype}${total !== '0' ? '\nTotal: Rp ' + Number(total).toLocaleString('id-ID') : ''}\nWaktu: ${now}`
}}];

const d = $('Route & Build Response').item.json;
const s = d.currentSession;
const su = d.sessionUpdate;
const resId = su.last_reservation_id || s.last_reservation_id;
const rname = su.reservation_name || s.reservation_name;
return [{ json: {
  reservation_id: resId, phone: d.phone, customer_name: rname,
  guests: su.reservation_guests || s.reservation_guests,
  date: su.reservation_date || s.reservation_date,
  time: su.reservation_time || s.reservation_time,
  status: 'confirmed', created_at: new Date().toISOString(),
  owner_msg: `*RESERVASI BARU!*\nNo: ${resId}\nNama: ${rname}\nHP: ${d.phone}\nTamu: ${su.reservation_guests || s.reservation_guests} orang\nTanggal: ${su.reservation_date || s.reservation_date}\nJam: ${su.reservation_time || s.reservation_time}`
}}];
